<template><div class="table-wrap"><table><thead><tr><th>Code</th><th>Nom de la catégorie</th><th>Description de la catégorie</th><th>Réparateurs attachés</th><th>Statut</th><th>Actions</th></tr></thead><tbody><tr v-for="category in categories" :key="category.id"><td>#{{ String(category.id).padStart(2,'0') }}</td><td class="name"><img v-if="category.photo" class="category-photo" :src="category.photo" :alt="category.name"><span v-else :class="['category-icon',category.color]">{{ category.icon }}</span><strong>{{ category.name }}</strong></td><td class="description">{{ category.description }}</td><td><strong>{{ category.repairers }} réparateur{{ category.repairers > 1 ? 's' : '' }}</strong></td><td><span :class="['badge',category.active?'active':'inactive']">● {{ category.active ? 'Active' : 'Inactive' }}</span></td><td class="actions"><button @click="$emit('edit',category)">✎ Modifier</button><button class="delete" aria-label="Supprimer" @click="$emit('delete',category)">♜</button></td></tr><tr v-if="!categories.length"><td class="empty" colspan="6">Aucune catégorie ne correspond à votre recherche.</td></tr></tbody></table></div></template>
<script setup>defineProps({categories:{type:Array,required:true}});defineEmits(['edit','delete'])</script>
<style scoped>.table-wrap{overflow:auto;border:1px solid #e1ecfa;border-radius:9px}table{border-collapse:collapse;width:100%;min-width:930px;background:#fff}th{text-align:left;text-transform:uppercase;font-size:11px;color:#265aab;background:#edf8f5;padding:13px 14px}td{padding:17px 14px;border-bottom:1px solid #e5eef9;color:#113f85;font-size:13px}tr:last-child td{border-bottom:0}.name{display:flex;align-items:center;gap:15px;min-width:210px;color:#174b50}.category-icon,.category-photo{width:54px;height:54px;border-radius:13px}.category-icon{display:grid;place-items:center;font-size:25px}.category-photo{object-fit:cover}.blue{background:#e0efff;color:#087f70}.orange{background:#fff0e1;color:#ff861f}.violet{background:#eae4ff;color:#7140ed}.green{background:#d9f7f0;color:#00a87b}.pink{background:#ffe1eb;color:#ff426d}.description{max-width:310px;color:#5273a6;line-height:1.4}.badge{display:inline-block;padding:7px 12px;border-radius:18px;font-size:12px}.active{background:#dff8ef;color:#009f72}.inactive{background:#e9f1fb;color:#5878ad}.actions{white-space:nowrap}.actions button{padding:9px 14px;background:#fff;border:1px solid #8ec0ff;border-radius:7px;color:#087f70;font-size:12px}.actions .delete{margin-left:9px;border-color:#ff9dae;color:#ff3858;padding:9px 12px}.empty{text-align:center;padding:35px;color:#6381b5}</style>
